begin;
with j as (select * from jsonb_to_recordset($law7d0028$[{"code_id":"GK_RF","article_number":"57","version_date":"1994-11-30","article_text":"1. Реорганизация юридического лица (слияние, присоединение, разделение, выделение, преобразование) может быть осуществлена по решению его учредителей (участников) или органа юридического лица, уполномоченного на то учредительным документом.\n\nДопускается реорганизация юридического лица с одновременным сочетанием различных ее форм, предусмотренных абзацем первым настоящего пункта.\n\nДопускается реорганизация с участием двух и более юридических лиц, в том числе созданных в разных организационно-правовых формах, если настоящим Кодексом или другим законом предусмотрена возможность преобразования юридического лица одной из таких организационно-правовых форм в юридическое лицо другой из таких организационно-правовых форм.\n\nОграничения реорганизации юридических лиц могут быть установлены законом.\n\nОсобенности реорганизации кредитных, страховых, клиринговых организаций, специализированных финансовых обществ, специализированных обществ проектного финансирования, профессиональных участников рынка ценных бумаг, акционерных инвестиционных фондов, управляющих компаний инвестиционных фондов, паевых инвестиционных фондов и негосударственных пенсионных фондов, негосударственных пенсионных фондов и иных некредитных финансовых организаций, акционерных обществ работников (народных предприятий) определяются законами, регулирующими деятельность таких организаций.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n2. В случаях, установленных законом, реорганизация юридического лица в форме его разделения или выделения из его состава одного или нескольких юридических лиц осуществляется по решению уполномоченных государственных органов или по решению суда.\n\nЕсли учредители (участники) юридического лица, уполномоченный ими орган или орган юридического лица, уполномоченный на реорганизацию его учредительным документом, не осуществят реорганизацию юридического лица в срок, определенный в решении уполномоченного государственного органа, суд по иску указанного государственного органа назначает в установленном законом порядке арбитражного управляющего юридическим лицом и поручает ему осуществить реорганизацию юридического лица. С момента назначения арбитражного управляющего к нему переходят полномочия по управлению делами юридического лица. Арбитражный управляющий выступает от имени юридического лица в суде, составляет передаточный акт и передает его на рассмотрение суда вместе с учредительными документами юридических лиц, создаваемых в результате реорганизации. Решение суда об утверждении указанных документов является основанием для государственной регистрации вновь создаваемых юридических лиц. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n3. В случаях, установленных законом, реорганизация юридических лиц в форме слияния, присоединения или преобразования может быть осуществлена лишь с согласия уполномоченных государственных органов.\n\nПри реорганизации юридического лица в форме присоединения к нему другого юридического лица первое из них считается реорганизованным с момента внесения в единый государственный реестр юридических лиц записи о прекращении деятельности присоединенного юридического лица.\n\nГосударственная регистрация юридического лица, создаваемого в результате реорганизации (в случае регистрации нескольких юридических лиц - первого по времени государственной регистрации), допускается не ранее истечения соот\n\nветствующего срока для обжалования решения о реорганизации (пункт 1 статьи 601). (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 57. Реорганизация юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb62e3552540543d9beba57248c1046441e742eee53f966ee7109bb0932783b2"},{"code_id":"GK_RF","article_number":"58","version_date":"1994-11-30","article_text":"К отношениям, возникающим при реорганизации юридического лица в форме преобразования, правила статьи 60 настоящего Кодекса не применяются.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 58. Правопреемство при реорганизации юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a62965afc36ddf546c1f64968187f46f8d37318f95cb577a40a33022892e8cb6"},{"code_id":"GK_RF","article_number":"59","version_date":"1994-11-30","article_text":"1. Передаточный акт должен содержать положения о правопреемстве по всем обязательствам реорганизованного юридического лица в отношении всех его кредиторов и должников, включая обязательства, оспариваемые сторонами, а также порядок определения правопреемства в связи с изменением вида, состава, стоимости имущества, возникновением, изменением, прекращением прав и обязанностей реорганизуемого юридического лица, которые могут произойти после даты, на которую составлен передаточный акт.\n\n2. Передаточный акт утверждается учредителями (участниками) юридического лица или органом, принявшим решение о реорганизации юридического лица, и представляется вместе с учредительными документами для государственной регистрации юридических лиц, создаваемых в результате реорганизации, или внесения изменений в учредительные документы существующих юридических лиц.\n\nНепредставление вместе с учредительными документами передаточного акта, отсутствие в нем положений о правопреемстве по всем обязательствам реорганизованного юридического лица влекут отказ в государственной регистрации юридических лиц, создаваемых в результате реорганизации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 59. Передаточный акт","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44635f9abadb692d2594b228d7414c20a8de0a6dfa46ec24900b2dcbc8989a55"},{"code_id":"GK_RF","article_number":"60","version_date":"1994-11-30","article_text":"1. В течение трех рабочих дней после даты принятия решения о реорганизации юридического лица оно обязано уведомить в письменной форме уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, о начале процедуры реорганизации с указанием формы реорганизации. В случае участия в реорганизации двух и более юридических лиц такое уведомление направляется юридическим лицом, последним принявшим решение о реорганизации или определенным решением о реорганизации. На основании такого уведомления уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, вносит в единый государственный реестр юридических лиц запись о том, что юридические лица находятся в процессе реорганизации.\n\nРеорганизуемое юридическое лицо после внесения в единый государственный реестр юридических лиц записи о начале процедуры реорганизации дважды с периодичностью один раз в месяц опубликовывает в средствах массовой информации, в которых опубликовываются данные о государственной регистрации юридических лиц, уведомление о своей реорганизации. В случае участия в реорганизации двух и более юридических лиц уведомление о реорганизации опубликовывается от имени всех участвующих в реорганизации юридических лиц юридическим лицом, последним принявшим решение о реорганизации или определенным решением о реорганизации. В уведомлении о реорганизации указываются сведения о каждом участвующем в реорганизации, создаваемом или продолжающем деятельность в результате реорганизации юридическом лице, форма реорганизации, описание порядка и условий заявления кредиторами своих требований, иные сведения, предусмотренные законом.\n\nЗаконом может быть предусмотрена обязанность реорганизуемого юридического лица уведомить в письменной форме кредиторов о своей реорганизации.\n\n2. Кредитор юридического лица, если его права требования возникли до опубликования первого уведомления о реорганизации юридического лица, вправе потребовать в судебном порядке досрочного исполнения соответствующего обязательства должником, а при невозможности досрочного исполнения - прекращения обязательства и возмещения связанных с этим убытков, за исключением случаев, установленных законом или соглашением кредитора с реорганизуемым юридическим лицом.\n\nТребования о досрочном исполнении обязательства или прекращении обязательства и возмещении убытков могут быть предъявлены кредиторами не позднее чем в течение тридцати дней после даты опубликования последнего уведомления о реорганизации юридического лица.\n\nПраво, предусмотренное абзацем первым настоящего пункта, не предоставляется кредитору, уже имеющему достаточное обеспечение.\n\nПредъявленные в указанный срок требования должны быть исполнены до завершения процедуры реорганизации, в том числе внесением долга в депозит в случаях, предусмотренных статьей 327 настоящего Кодекса.\n\nКредитор не вправе требовать досрочного исполнения обязательства или прекращения обязательства и возмещения убытков, если в течение тридцати дней с даты предъявления кредитором этих требований ему будет предоставлено обеспечение, признаваемое достаточным в соответствии с пунктом 4 настоящей статьи.\n\nПредъявление кредиторами требований на основании настоящего пункта не является основанием для приостановления процедуры реорганизации юридического лица.\n\n3. Если кредитору, потребовавшему в соответствии с правилами настоящей статьи досрочного исполнения обязательства или прекращения обязательства и возмещения убытков, такое исполнение не предоставлено, убытки не возмещены и не предложено достаточное обеспечение исполнения обязательства, солидарную ответственность перед кредитором наряду с юридическими лицами, созданными в результате реорганизации, несут лица, имеющие фактическую возможность определять действия реорганизованных юридических лиц (пункт 3 статьи 531), члены их коллегиальных органов и лицо, уполномоченное выступать от имени реорганизованного юридического лица (пункт 3 статьи 53), если они своими действиями (бездействием) способствовали наступлению указанных последствий для кредитора, а при реорганизации в форме выделения солидарную ответственность перед кредитором наряду с указанными лицами несет также реорганизованное юридическое лицо.\n\n4. Предложенное кредитору обеспечение исполнения обязательств реорганизуемого юридического лица или возмещения связанных с его прекращением убытков считается достаточным, если:\n\n1) кредитор согласился принять такое обеспечение;\n\n2) кредитору выдана независимая безотзывная гарантия кредитной организацией, кредитоспособность которой не вызывает обоснованных сомнений, со сроком действия, не менее чем на три месяца превышающим срок исполнения обеспечиваемого обязательства, и с условием платежа по предъявлении кредитором требований к гаранту с приложением доказательств неисполнения обязательства реорганизуемого или реорганизованного юридического лица.\n\n5. Если передаточный акт не позволяет определить правопреемника по обязательству юридического лица, а также если из передаточного акта или иных обстоятельств следует, что при реорганизации недобросовестно распределены активы и обязательства реорганизуемых юридических лиц, что привело к существенному нарушению интересов кредиторов, реорганизованное юридическое лицо и созданные в результате реорганизации юридические лица несут солидарную ответственность по такому обязательству.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60. Гарантии прав кредиторов реорганизуемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afa9ef0ca3e780a46f3e80b8e6da36a15709c35e74e04186171fd9f7a4d5433d"},{"code_id":"GK_RF","article_number":"60.1","version_date":"1994-11-30","article_text":"1. Решение о реорганизации юридического лица может быть признано недействительным по требованию участников реорганизуемого юридического лица, а также иных лиц, не являющихся участниками юридического лица, если такое право им предоставлено законом.\n\nУказанное требование может быть предъявлено в суд не позднее чем в течение трех месяцев после внесения в единый государственный реестр юридических лиц записи о начале процедуры реорганизации, если иной срок не установлен законом.\n\n2. Признание судом недействительным решения о реорганизации юридического лица не влечет ликвидации образовавшегося в результате реорганизации юридического лица, а также не является основанием для признания недействительными сделок, совершенных таким юридическим лицом.\n\n3. В случае признания решения о реорганизации юридического лица недействительным до окончания реорганизации, если осуществлена государственная регистрация части юридических лиц, подлежащих созданию в результате реорганизации, правопреемство наступает только в отношении таких зарегистрированных юридических лиц, в остальной части права и обязанности сохраняются за прежними юридическими лицами.\n\n4. Лица, недобросовестно способствовавшие принятию признанного судом недействительным решения о реорганизации, обязаны солидарно возместить убытки участнику реорганизованного юридического лица, голосовавшему против принятия решения о реорганизации или не принимавшему участия в голосовании, а также кредиторам реорганизованного юридического лица. Солидарно с данными лицами, недобросовестно способствовавшими принятию решения о реорганизации, отвечают юридические лица, созданные в результате реорганизации на основании указанного решения.\n\nЕсли решение о реорганизации юридического лица принималось коллегиальным органом, солидарная ответственность возлагается на членов этого органа, голосовавших за принятие соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60.1. Последствия признания недействительным решения о реорганизации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aabbd8184002f6ac7ad202f48b16a5289f29b3801deede954982c8d7d7113f9a"},{"code_id":"GK_RF","article_number":"60.2","version_date":"1994-11-30","article_text":"1. Суд по требованию участника корпорации, голосовавшего против принятия решения о реорганизации этой корпорации или не принимавшего участия в голосовании по данному вопросу, может признать реорганизацию несостоявшейся в случае, если решение о реорганизации не принималось участниками реорганизованной корпорации, а также в случае представления для государственной регистрации юридических лиц, создаваемых путем реорганизации, документов, содержащих заведомо недостоверные данные о реорганизации.\n\n2. Решение суда о признании реорганизации несостоявшейся влечет следующие правовые последствия:\n\n1) восстанавливаются юридические лица, существовавшие до реорганизации, с одновременным прекращением юридических лиц, созданных в результате реорганизации, о чем делаются соответствующие записи в едином государственном реестре юридических лиц;\n\n2) сделки юридических лиц, созданных в результате реорганизации, с лицами, добросовестно полагавшимися на правопреемство, сохраняют силу для восстановленных юридических лиц, которые являются солидарными должниками и солидарными кредиторами по таким сделкам;\n\n3) переход прав и обязанностей признается несостоявшимся, при этом предоставление (платежи, услуги и т.п.), осуществленное в пользу юридического лица, созданного в результате реорганизации, должниками, добросовестно полагавшимися на правопреемство на стороне кредитора, признается совершенным в пользу управомоченного лица. Если за счет имущества (активов) одного из юридических лиц, участвовавших в реорганизации, исполнены обязанности другого из них, перешедшие к юридическому лицу, созданному в результате реорганизации, к отношениям указанных лиц применяются правила об обязательствах вследствие неосновательного обогащения (глава 60). Произведенные выплаты могут быть оспорены по заявлению лица, за счет средств которого они были произведены, если получатель исполнения знал или должен был знать о незаконности реорганизации;\n\n4) участники ранее существовавшего юридического лица признаются обладателями долей участия в нем в том размере, в котором доли принадлежали им до реорганизации, а при смене участников юридического лица в ходе такой реорганизации или по ее окончании доли участия участников ранее существовавшего юридического лица возвращаются им по правилам, предусмотренным пунктом 3 статьи 652 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60.2. Признание реорганизации корпорации несостоявшейся","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"479c6f31c9787e7f4ef198872dd4e62803a0075d259c2fa680fc81fa47ce6d55"},{"code_id":"GK_RF","article_number":"61","version_date":"1994-11-30","article_text":"1. Ликвидация юридического лица влечет его прекращение без перехода в порядке универсального правопреемства его прав и обязанностей к другим лицам.\n\n2. Юридическое лицо ликвидируется по решению его учредителей (участников) или органа юридического лица, уполномоченного на то учредительным документом, в том числе в связи с истечением срока, на который создано юридическое лицо, с достижением цели, ради которой оно создано.\n\n3. Юридическое лицо ликвидируется по решению суда:\n\n1) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае признания государственной регистрации юридического лица недействительной, в том числе в связи с допущенными при его создании грубыми нарушениями закона, если эти нарушения носят неустранимый характер;\n\n2) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае осуществления юридическим лицом деятельности без надлежащего разрешения (лицензии) либо при отсутствии обязательного членства в саморегулируемой организации или необходимого в силу закона свидетельства о допуске к определенному виду работ, выданного саморегулируемой организацией;\n\n3) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае осуществления юридическим лицом деятельности, запрещенной законом, либо с нарушением Конституции Российской Федерации, либо с другими неоднократными или грубыми нарушениями закона или иных правовых актов;\n\n4) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае систематического осуществления общественной организацией, общественным движением, общественно полезным фондом, религиозной организацией деятельности, противоречащей уставным целям таких организаций; (В редакции  федеральных законов от 23.05.2015 № 133-ФЗ, от 08.08.2024 № 237-ФЗ)\n\n5) по иску учредителя (участника) юридического лица в случае невозможности достижения целей, ради которых оно создано, в том числе в случае, если осуществление деятельности юридического лица становится невозможным или существенно затрудняется;\n\n6) в иных случаях, предусмотренных законом.\n\n4. С момента принятия решения о ликвидации юридического лица срок исполнения его обязательств перед кредиторами считается наступившим.\n\n5. Решением суда о ликвидации юридического лица на его учредителей (участников) или на орган, уполномоченный на ликвидацию юридического лица его учредительным документом, могут быть возложены обязанности по осуществлению ликвидации юридического лица. Неисполнение решения суда является основанием для осуществления ликвидации юридического лица арбитражным управляющим (пункт 5 статьи 62) за счет имущества юридического лица. При недостаточности у юридического лица средств на расходы, необходимые для его ликвидации, эти расходы возлагаются на учредителей (участников) юридического лица солидарно (пункт 2 статьи 62).\n\n6. Юридические лица, за исключением предусмотренных статьей 65 настоящего Кодекса юридических лиц, по решению суда могут быть признаны несостоятельными (банкротами) и ликвидированы в случаях и в порядке, которые предусмотрены законодательством о несостоятельности (банкротстве).\n\nОбщие правила о ликвидации юридических лиц, содержащиеся в настоящем Кодексе, применяются к ликвидации юридического лица в порядке конкурсного производства в случаях, если настоящим Кодексом или законодательством о несостоятельности (банкротстве) не установлены иные правила.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 61. Ликвидация юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26e87903f1499122fe1d3efb0024b67cdb196d3277cc6ed94843e87f9e43df2b"},{"code_id":"GK_RF","article_number":"62","version_date":"1994-11-30","article_text":"1. Учредители (участники) юридического лица или орган, принявшие решение о ликвидации юридического лица, в течение трех рабочих дней после даты принятия данного решения обязаны сообщить в письменной форме об этом в уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, для внесения в единый государственный реестр юридических лиц записи о том, что юридическое лицо находится в процессе ликвидации, а также опубликовать сведения о принятии данного решения в порядке, установленном законом.\n\n2. Учредители (участники) юридического лица независимо от оснований, по которым принято решение о его ликвидации, в том числе в случае фактического прекращения деятельности юридического лица, обязаны совершить за счет имущества юридического лица действия по ликвидации юридического лица. При недостаточности имущества юридического лица учредители (участники) юридического лица обязаны совершить указанные действия солидарно за свой счет.\n\n3. Учредители (участники) юридического лица или орган, принявшие решение о ликвидации юридического лица, назначают ликвидационную комиссию (ликвидатора) и устанавливают порядок и сроки ликвидации в соответствии с законом.\n\n4. С момента назначения ликвидационной комиссии к ней переходят полномочия по управлению делами юридического лица. Ликвидационная комиссия от имени ликвидируемого юридического лица выступает в суде. Ликвидационная комиссия обязана действовать добросовестно и разумно в интересах ликвидируемого юридического лица, а также его кредиторов.\n\nЕсли ликвидационной комиссией установлена недостаточность имущества юридического лица для удовлетворения всех требований кредиторов, дальнейшая ликвидация юридического лица может осуществляться только в порядке, установленном законодательством о несостоятельности (банкротстве).\n\n5. В случае неисполнения или ненадлежащего исполнения учредителями (участниками) юридического лица обязанностей по его ликвидации заинтересованное лицо или уполномоченный государственный орган вправе потребовать в судебном порядке ликвидации юридического лица и назначения для этого арбитражного управляющего.\n\n6. При невозможности ликвидации юридического лица ввиду отсутствия средств на расходы, необходимые для его ликвидации, и невозможности возложить эти расходы на его учредителей (участников) юридическое лицо подлежит исключению из единого государственного реестра юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 62. Обязанности лиц, принявших решение о ликвидации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1e7fb2370ce440a740e34e447bc316f2c6edd19ad26dc4f6d31e5e4b9873719"},{"code_id":"GK_RF","article_number":"63","version_date":"1994-11-30","article_text":"1. Ликвидационная комиссия опубликовывает в средствах массовой информации, в которых опубликовываются данные о государственной регистрации юридического лица, сообщение о его ликвидации и о поряд\n\nке и сроке заявления требований его кредиторами. Этот срок не может быть менее двух месяцев с момента опубликования сообщения о ликвидации.\n\nЛиквидационная комиссия принимает меры по выявлению кредиторов и получению дебиторской задолженности, а также уведомляет в письменной форме кредиторов о ликвидации юридического лица.\n\n2. После окончания срока предъявления требований кредиторами ликвидационная комиссия составляет промежуточный ликвидационный баланс, который содержит сведения о составе имущества ликвидируемого юридического лица, перечне требований, предъявленных кредиторами, результатах их рассмотрения, а также о перечне требований, удовлетворенных вступившим в законную силу решением суда, независимо от того, были ли такие требования приняты ликвидационной комиссией.\n\nПромежуточный ликвидационный баланс утверждается учредителями (участниками) юридического лица или органом, принявшими решение о ликвидации юридического лица. В случаях, установленных законом, промежуточный ликвидационный баланс утверждается по согласованию с уполномоченным государственным органом.\n\n3. В случае возбуждения дела о несостоятельности (банкротстве) юридического лица его ликвидация, осуществляемая по правилам настоящего Кодекса, прекращается и ликвидационная комиссия уведомляет об этом всех известных ей кредиторов. Требования кредиторов в случае прекращения ликвидации юридического лица при возбуждении дела о его несостоятельности (банкротстве) рассматриваются в порядке, установленном законодательством о несостоятельности (банкротстве).\n\n4. Если имеющиеся у ликвидируемого юридического лица (кроме учреждений) денежные средства недостаточны для удовлетворения требований кредиторов, ликвидационная комиссия осуществляет продажу имущества юридического лица, на которое в соответствии с законом допускается обращение взыскания, с торгов, за исключением объектов стоимостью не более ста тысяч рублей (согласно утвержденному промежуточному ликвидационному балансу), для продажи которых проведение торгов не требуется.\n\nВ случае недостаточности имущества ликвидируемого юридического лица для удовлетворения требований кредиторов или при наличии признаков банкротства юридического лица ликвидационная комиссия обязана обратиться в арбитражный суд с заявлением о банкротстве юридического лица, если такое юридическое лицо может быть признано несостоятельным (банкротом).\n\n5. Выплата денежных сумм кредиторам ликвидируемого юридического лица производится ликвидационной комиссией в порядке очередности, установленной статьей 64 настоящего Кодекса, в соответствии с промежуточным ликвидационным балансом со дня его утверждения.\n\n6. После завершения расчетов с кредиторами ликвидационная комиссия составляет ликвидационный баланс, который утверждается учредителями (участниками) юридического лица или органом, принявшими решение о ликвидации юридического лица. В случаях, установленных законом, ликвидационный баланс утверждается по согласованию с уполномоченным государственным органом.\n\n7. В случаях, если настоящим Кодексом предусмотрена субсидиарная ответственность собственника имущества учреждения или казенного предприятия по обязательствам этого учреждения или этого предприятия, при недостаточности у ликвидируемых учреждения или казенного предприятия имущества, на которое в соответствии с законом может быть обращено взыскание, кредиторы вправе обратиться в суд с иском об удовлетворении оставшейся части требований за счет собственника имущества этого учреждения или этого предприятия.\n\n8. Оставшееся после удовлетворения требований кредиторов имущество юридического лица передается его учредителям (участникам), имеющим вещные права на это имущество или корпоративные права в отношении юридического лица, если иное не предусмотрено законом, иными правовыми актами или учредительным документом юридического лица. При наличии спора между учредителями (участниками) относительно того, кому следует передать вещь, она продается ликвидационной комиссией с торгов. Если иное не установлено настоящим Кодексом или другим законом, при ликвидации некоммерческой организации оставшееся после удовлетворения требований кредиторов имущество направляется в соответствии с уставом некоммерческой организации на цели, для достижения которых она была создана, и (или) на благотворительные цели.\n\n9. Ликвидация юридического лица считается завершенной, а юридическое лицо - прекратившим существование после внесения сведений о его прекращении в единый государственный реестр юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 63. Порядок ликвидации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f36df59310bc06ef76570fc4fbcb3b5c24e04ce24488f4dc52c2544f8a0faa86"},{"code_id":"GK_RF","article_number":"64","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nв первую очередь удовлетворяются требования граждан, перед которыми ликвидируемое юридическое лицо несет ответственность за причинение вреда жизни или здоровью, путем капитализации соответствующих повременных платежей, о компенсации сверх возмещения вреда, причиненного вследствие разрушения, повреждения объекта капитального строительства, нарушения требований безопасности при строительстве объекта капитального строительства, требований к обеспечению безопасной эксплуатации здания, сооружения; (В редакции федеральных законов от 03.01.2006 № 6-ФЗ; от 28.11.2011 № 337-ФЗ; от 29.06.2015 № 186-ФЗ)\n\nво вторую очередь производятся расчеты по выплате выходных пособий и оплате труда лиц, работающих или работавших по трудовому договору, и по выплате вознаграждений авторам результатов интеллектуальной деятельности; (В редакции федеральных законов от 03.01.2006 № 6-ФЗ; от 18.12.2006 № 231-ФЗ)\n\nв третью очередь производятся расчеты по обязательным платежам в бюджет и во внебюджетные фонды; (В редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\nв четвертую очередь производятся расчеты с другими кредиторами. (В редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 03.01.2006 № 6-ФЗ)\n\nПри ликвидации банков, привлекающих средства граждан, в первую очередь удовлетворяются также требования граждан, являющихся кредиторами банков по заключенным с ними или в их пользу договорам банковского вклада или банковского счета, за исключением договоров, связанных с осуществлением гражданином предпринимательской или иной профессиональной деятельности, в части основной суммы задолженности и причитающихся процентов, требования организации, осуществляющей обязательное страхование вкладов, в связи с выплатой возмещения по вкладам в соответствии с законом о страховании вкладов граждан в банках и требования Банка России в связи с осуществлением выплат по вкладам граждан в банках в соответствии с законом. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nТребования кредиторов о возмещении убытков в виде упущенной выгоды, о взыскании неустойки (штрафа, пени), в том числе за неисполнение или ненадлежащее исполнение обязанности по уплате обязательных платежей, удовлетворяются после удовлетворения требований кредиторов первой, второй, третьей и четвертой очереди.  (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\nТребования кредиторов по обязательствам, обеспеченным залогом имущества ликвидируемого юридического лица, удовлетворяются за счет средств, полученных от продажи предмета залога, преимущественно перед иными кредиторами, за исключением обязательств перед кредиторами первой и второй очереди, права требования по которым возникли до заключения соответствующего договора залога.\n\nНе удовлетворенные за счет средств, полученных от продажи предмета залога, требования кредиторов по обязательствам, обеспеченным залогом имущества ликвидируемого юридического лица, удовлетворяются в составе требований кредиторов четвертой очереди.\n\n(Пункт в редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\n1) требования кредиторов, не удовлетворенные по причине недостаточности имущества ликвидируемого юридического лица и не удовлетворенные за счет имущества лиц, несущих субсидиарную ответственность по таким требованиям, если ликвидируемое юридическое лицо в случаях, предусмотренных статьей 65 настоящего Кодекса, не может быть признано несостоятельным (банкротом);\n\n2) требования, не признанные ликвидационной комиссией, если кредиторы по таким требованиям не обращались с исками в суд;\n\n3) требования, в удовлетворении которых решением суда кредиторам отказано.\n\n(Дополнение пунктом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\nЗаявление о назначении процедуры распределения обнаруженного имущества ликвидированного юридического лица может быть подано в течение пяти лет с момента внесения в единый государственный реестр юридических лиц сведений о прекращении юридического лица. Процедура распределения обнаруженного имущества ликвидированного юридического лица может быть назначена при наличии средств, достаточных для осуществления данной процедуры, и возможности распределения обнаруженного имущества среди заинтересованных лиц.\n\nПроцедура распределения обнаруженного имущества ликвидированного юридического лица осуществляется по правилам настоящего Кодекса о ликвидации юридических лиц.\n\n(Дополнение пунктом - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64. Удовлетворение требований кредиторов ликвидируемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f9fa4758b8c113a46030a9bf2d2b1edbead93b51f06335a771a898854aac1059"},{"code_id":"GK_RF","article_number":"64.1","version_date":"1994-11-30","article_text":"1. В случае отказа ликвидационной комиссии удовлетворить требование кредитора или уклонения от его рассмотрения кредитор до утверждения ликвидационного баланса юридического лица вправе обратиться в суд с иском об удовлетворении его требования к ликвидируемому юридическому лицу. В случае удовлетворения судом иска кредитора выплата присужденной ему денежной суммы производится в порядке очередности, установленной статьей 64 настоящего Кодекса.\n\n2. Члены ликвидационной комиссии (ликвидатор) по требованию учредителей (участников) ликвидированного юридического лица или по требованию его кредиторов обязаны возместить убытки, причиненные ими учредителям (участникам) ликвидированного юридического лица или его кредиторам, в порядке и по основаниям, которые предусмотрены статьей 531 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64.1. Защита прав кредиторов ликвидируемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03723cda952ad6fa6deb4e7f0fd857ec6ce8856df0718ed8e972f45658d3a4da"},{"code_id":"GK_RF","article_number":"64.2","version_date":"1994-11-30","article_text":"1. Считается фактически прекратившим свою деятельность и подлежит исключению из единого государственного реестра юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц, юридическое лицо, которое в течение двенадцати месяцев, предшествующих его исключению из указанного реестра, не представляло документы отчетности, предусмотренные законодательством Российской Федерации о налогах и сборах, и не осуществляло операций хотя бы по одному банковскому счету (недействующее юридическое лицо).\n\n2. Исключение недействующего юридического лица из единого государственного реестра юридических лиц влечет правовые последствия, предусмотренные настоящим Кодексом и другими законами применительно к ликвидированным юридическим лицам.\n\n3. Исключение недействующего юридического лица из единого государственного реестра юридических лиц не препятствует привлечению к ответственности лиц, указанных в статье 531 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64.2. Прекращение недействующего юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"527d8e38c0c33246426a83399cb1d4fb9aeee87cadda09778c43d5db9c9693c0"},{"code_id":"GK_RF","article_number":"65","version_date":"1994-11-30","article_text":"Признание юридического лица банкротом судом влечет его ликвидацию.","article_title":"Статья 65. Несостоятельность (банкротство) юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0150d1c535f9f5ace6d16ecc5bc72f7f65aac6b26435d98df4f39cf2b7dffce5"},{"code_id":"GK_RF","article_number":"65.1","version_date":"1994-11-30","article_text":"Юридические лица, учредители которых не становятся их участниками и не приобретают в них прав членства, являются унитарными юридическими лицами. К ним относятся государственные и муниципальные унитарные предприятия, общественно полезные фонды, личные фонды, учреждения, автономные некоммерческие организации, религиозные организации, государственные корпорации, публично-правовые компании. (В редакции федеральных законов от 03.07.2016 № 236-ФЗ, от 01.07.2021 № 287-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.1. Корпоративные и унитарные юридические лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6cb717c0371e22a0005a57849d04d4c2421050a883248702afebbe0646f18a6c"},{"code_id":"GK_RF","article_number":"65.2","version_date":"1994-11-30","article_text":"1. Участники корпорации (участники, члены, акционеры и т.п.) вправе:\n\nучаствовать в управлении делами корпорации, за исключением случая, предусмотренного пунктом 2 статьи 84 настоящего Кодекса;\n\nв случаях и в порядке, которые предусмотрены законом и учредительным документом корпорации, получать информацию о деятельности корпорации и знакомиться с ее бухгалтерской и иной документацией;\n\nобжаловать решения органов корпорации, влекущие гражданско-правовые последствия, в случаях и в порядке, которые предусмотрены законом;\n\nтребовать, действуя от имени корпорации (пункт 1 статьи 182), возмещения причиненных корпорации убытков (статья 531);\n\nоспаривать, действуя от имени корпорации (пункт 1 статьи 182), совершенные ею сделки по основаниям, предусмотренным статьей 174 настоящего Кодекса или законами о корпорациях отдельных организационно-правовых форм, и требовать применения последствий их недействительности, а также применения последствий недействительности ничтожных сделок корпорации.\n\nУчастники корпорации могут иметь и другие права, предусмотренные законом или учредительным документом корпорации.\n\n2. Участник корпорации или корпорация, требующие возмещения причиненных корпорации убытков (статья 531) либо признания сделки корпорации недействительной или применения последствий недействительности сделки, должны принять разумные меры по заблаговременному уведомлению других участников корпорации и в соответствующих случаях корпорации о намерении обратиться с такими требованиями в суд, а также предоставить им иную информацию, имеющую отношение к делу. Порядок уведомления о намерении обратиться в суд с иском может быть предусмотрен законами о корпорациях и учредительным документом корпорации.\n\nУчастники корпорации, не присоединившиеся в порядке, установленном процессуальным законодательством, к иску о возмещении причиненных корпорации убытков (статья 531) либо к иску о признании недействительной совершенной корпорацией сделки или о применении последствий недействительности сделки, в последующем не вправе обращаться в суд с тождественными требованиями, если только суд не признает причины этого обращения уважительными.\n\n3. Если иное не установлено настоящим Кодексом, участник коммерческой корпорации, утративший помимо своей воли в результате неправомерных действий других участников или третьих лиц права участия в ней, вправе требовать возвращения ему доли участия, перешедшей к иным лицам, с выплатой им справедливой компенсации, определяемой судом, а также возмещения убытков за счет лиц, виновных в утрате доли. Суд может отказать в возвращении доли участия, если это приведет к несправедливому лишению иных лиц их прав участия или повлечет крайне негативные социальные и другие публично значимые последствия. В этом случае лицу, утратившему помимо своей воли права участия в корпорации, лицами, виновными в утрате доли участия, выплачивается справедливая компенсация, определяемая судом.\n\n4. Участник корпорации обязан:\n\nучаствовать в образовании имущества корпорации в необходимом размере в порядке, способом и в сроки, которые предусмотрены настоящим Кодексом, другим законом или учредительным документом корпорации;\n\nне разглашать конфиденциальную информацию о деятельности корпорации;\n\nучаствовать в принятии корпоративных решений, без которых корпорация не может продолжать свою деятельность в соответствии с законом, если его участ\n\nие необходимо для принятия таких решений;\n\nне совершать действия, заведомо направленные на причинение вреда корпорации;\n\nне совершать действия (бездействие), которые существенно затрудняют или делают невозможным достижение целей, ради которых создана корпорация.\n\nУчастники корпорации могут нести и другие обязанности, предусмотренные законом или учредительным документом корпорации.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.2. Права и обязанности участников корпорации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"666f4660f146fb80cfc52b63627c6ffe42cf8331e6680623af756b6eb0bb1b8a"},{"code_id":"GK_RF","article_number":"65.3","version_date":"1994-11-30","article_text":"1. Высшим органом корпорации является общее собрание ее участников.\n\nВ некоммерческих корпорациях и производственных кооперативах с числом участников более ста высшим органом может являться съезд, конференция или иной представительный (коллегиальный) орган, определяемый их уставами в соответствии с законом. Компетенция этого органа и порядок принятия им решений определяются настоящим Кодексом, другими законами и уставом корпорации. (В редакции Федерального закона от 23.05.2015 № 133-ФЗ)\n\n2. Если иное не предусмотрено настоящим Кодексом или другим законом, к исключительной компетенции высшего органа корпорации относятся:\n\nопределение приоритетных направлений деятельности корпорации, принципов образования и использования ее имущества;\n\nутверждение и изменение устава корпорации;\n\nопределение порядка приема в состав участников корпорации и исключения из числа ее участников, кроме случаев, если такой порядок определен законом;\n\nобразование других органов корпорации и досрочное прекращение их полномочий, если уставом корпорации в соответствии с законом это правомочие не отнесено к компетенции иных коллегиальных органов корпорации;\n\nутверждение годовых отчетов и бухгалтерской (финансовой) отчетности корпорации, если уставом корпорации в соответствии с законом это правомочие не отнесено к компетенции иных коллегиальных органов корпорации;\n\nпринятие решений о создании корпорацией других юридических лиц, об участии корпорации в других юридических лицах, о создании филиалов и об открытии представительств корпорации, за исключением случаев, если уставом хозяйственного общества в соответствии с законами о хозяйственных обществах принятие таких решений по указанным вопросам отнесено к компетенции иных коллегиальных органов корпорации;\n\nпринятие решений о реорганизации и ликвидации корпорации, о назначении ликвидационной комиссии (ликвидатора) и об утверждении ликвидационного баланса;\n\nизбрание ревизионной комиссии (ревизора) и назначение аудиторской организации или индивидуального аудитора корпорации.\n\nЗаконом и учредительным документом корпорации к исключительной компетенции ее высшего органа может быть отнесено решение иных вопросов.\n\nВопросы, отнесенные настоящим Кодексом и другими законами к исключительной компетенции высшего органа корпорации, не могут быть переданы им для решения другим органам корпорации, если иное не предусмотрено настоящим Кодексом или другим законом.\n\n3. В корпорации образуется единоличный исполнительный орган (директор, генеральный директор, председатель и т.п.). Уставом корпорации может быть предусмотрено предоставление полномочий единоличного исполнительного органа нескольким лицам, действующим совместно, или образование нескольких единоличных исполнительных органов, действующих независимо друг от друга (абзац третий пункта 1 статьи 53). В качестве единоличного исполнительного органа корпорации может выступать как физическое лицо, так и юридическое лицо.\n\nВ случаях, предусмотренных настоящим Кодексом, другим законом или уставом корпорации, в корпорации образуется коллегиальный исполнительный орган (правление, дирекция и т.п.).\n\nК компетенции указанных в настоящем пункте органов корпорации относится решение вопросов, не входящих в компетенцию ее высшего органа и созданного в соответствии с пунктом 4 настоящей статьи коллегиального органа управления.\n\n4. Наряду с исполнительными органами, указанными в пункте 3 настоящей статьи, в корпорации может быть образован в случаях, предусмотренных настоящим Кодексом, другим законом или уставом корпорации, коллегиальный орган управления (наблюдательный или иной совет), контролирующий деятельность исполнительных органов корпорации и выполняющий иные функции, возложенные на него законом или уставом корпорации. Лица, осуществляющие полномочия единоличных исполнительных органов корпораций, и члены их коллегиальных исполнительных органов не могут составлять более одной четверти состава коллегиальных органов управления корпораций и не могут являться их председателями.\n\nЧлены коллегиального органа управления корпорации имеют право получать информацию о деятельности корпорации и знакомиться с ее бухгалтерской и иной документацией, требовать возмещения причиненных корпорации убытков (статья 531), оспаривать совершенные корпорацией сделки по основаниям, предусмотренным статьей 174 настоящего Кодекса или законами о корпорациях отдельных организационно-правовых форм, и требовать применения последствий их недействительности, а также требовать применения последствий недействительности ничтожных сделок корпорации в порядке, установленном пунктом 2 статьи 652 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Общие положения о хозяйственных товариществах и обществах\n\n(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.3. Управление в корпорации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5885b6b11e1444d4df937c65d1e727a6b048ae3e2cce8b0b24ad82158a1547e1"},{"code_id":"GK_RF","article_number":"66","version_date":"1994-11-30","article_text":"1. Хозяйственными товариществами и обществами признаются корпоративные коммерческие организации с разделенным на доли (вклады) учредителей (участников) уставным (складочным) капиталом. Имущество, созданное за счет вкладов учредителей (участников), а также произведенное и приобретенное хозяйственным товариществом или обществом в процессе деятельности, принадлежит на праве собственности хозяйственному товариществу или обществу.\n\nОбъем правомочий участников хозяйственного общества определяется пропорционально их долям в уставном капитале общества. Иной объем правомочий участников непубличного хозяйственного общества может быть предусмотрен уставом общества, а также корпоративным договором при условии внесения сведений о наличии такого договора и о предусмотренном им объеме правомочий участников общества в единый государственный реестр юридических лиц.\n\nХозяйственное общество может иметь в качестве единственного участника другое хозяйственное общество, состоящее из одного лица, если иное не установлено настоящим Кодексом или другим законом. (В редакции  Федерального закона от 24.06.2025 № 178-ФЗ)\n\nУчастниками хозяйственных обществ и вкладчиками в товариществах на вере могут быть граждане и юридические лица, а также публично-правовые образования (статья 125).\n\nУчреждения могут быть участниками хозяйственных обществ и вкладчиками в товариществах на вере с разрешения собственника имущества учреждения, если иное не установлено законом.\n\nЗаконом может быть запрещено или ограничено участие отдельных категорий лиц в хозяйственных товариществах и обществах.\n\nХозяйственные товарищества и общества могут быть учредителями (участниками) других хозяйственных товариществ и обществ, за исключением случаев, предусмотренных законом.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66. Основные положения о хозяйственных товариществах и обществах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e74c2187f22a19a617a8eda47f223df53424d60d4bb064cb04067698e0ec61c8"},{"code_id":"GK_RF","article_number":"66.1","version_date":"1994-11-30","article_text":"1. Вкладом участника хозяйственного товарищества или общества в его имущество могут быть денежные средства, вещи, доли (акции) в уставных (складочных) капиталах других хозяйственных товариществ и обществ, государственные и муниципальные облигации. Таким вкладом также могут быть подлежащие денежной оценке исключительные, иные интеллектуальные права и права по лицензионным договорам, если иное не установлено законом.\n\n2. Законом или учредительными документами хозяйственного товарищества или общества могут быть установлены виды указанного в пункте 1 настоящей статьи имущества, которое не может быть внесено для оплаты долей в уставном (складочном) капитале хозяйственного товарищества или общества.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.1. Вклады в имущество хозяйственного товарищества или общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63de0cf28ee90c92000abd9a66b37f409dced58c044f37d4167a06ef7441740f"},{"code_id":"GK_RF","article_number":"66.2","version_date":"1994-11-30","article_text":"1. Минимальный размер уставных капиталов хозяйственных обществ определяется законами о хозяйственных обществах.\n\nМинимальные размеры уставных капиталов хозяйственных обществ, осуществляющих банковскую, страховую или иную подлежащую лицензированию деятельность, а также акционерных обществ, использующих открытую (публичную) подписку на свои акции, устанавливаются законами, определяющими особенности правового положения указанных хозяйственных обществ.\n\n2. При оплате уставного капитала хозяйственного общества должны быть внесены денежные средства в сумме не ниже минимального размера уставного капитала (пункт 1 настоящей статьи).\n\nДенежная оценка неденежного вклада в уставный капитал хозяйственного общества должна быть проведена независимым оценщиком. Участники хозяйственного общества не вправе определять денежную оценку неденежного вклада в размере, превышающем сумму оценки, определенную независимым оценщиком.\n\n3. При оплате долей в уставном капитале общества с ограниченной ответственностью не денежными средствами, а иным имуществом участники общества и независимый оценщик в случае недостаточности имущества общества солидарно несут субсидиарную ответственность по его обязательствам в пределах суммы, на которую завышена оценка имущества, внесенного в уставный капитал, в течение пяти лет с момента государственной регистрации общества или внесения в устав общества соответствующих изменений. При внесении в уставный капитал акционерного общества не денежных средств, а иного имущества акционер, осуществивший такую оплату, и независимый оценщик в случае недостаточности имущества общества солидарно несут субсидиарную ответственность по его обязательствам в пределах суммы, на которую завышена оценка имущества, внесенного в уставный капитал, в течение пяти лет с момента государственной регистрации общества или внесения в устав общества соответствующих изменений.\n\nПравила настоящего пункта об ответственности участника общества и независимого оценщика не применяются к хозяйственным обществам, созданным в соответствии с законами о приватизации путем приватизации государственных или муниципальных унитарных предприятий.\n\n4. Если иное не предусмотрено законами о хозяйственных обществах, учредители хозяйственного общества обязаны оплатить не менее трех четвертей его уставного капитала до государственной регистрации общества, а остальную часть уставного капитала хозяйственного общества - в течение первого года деятельности общества.\n\nВ случаях, если в соответствии с законом допускается государственная регистрация хозяйственного общества без предварительной оплаты трех четвертей уставного капитала, участники общества несут субсидиарную ответственность по его обязательствам, возникшим до момента полной оплаты уставного капитала.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.2. Основные положения об уставном капитале хозяйственного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"465bfe0b49bef43f2c24eec0c0d6eb6b074b19e6b405386cd11c5cb4ae5c6403"},{"code_id":"GK_RF","article_number":"66.3","version_date":"1994-11-30","article_text":"1. Публичным является акционерное общество, акции которого и ценные бумаги которого, конвертируемые в его акции, публично размещаются (путем открытой подписки) или публично обращаются на условиях, установленных законами о ценных бумагах. Правила о публичных обществах применяются также к акционерным обществам, устав и фирменное наименование которых содержат указание на то, что общество является публичным.\n\n2. Общество с ограниченной ответственностью и акционерное общество, которое не отвечает признакам, указанным в пункте 1 настоящей статьи, признаются непубличными.\n\n3. По решению участников (учредителей) непубличного общества, принятому единогласно, в устав общества могут быть включены следующие положения:\n\n1) о передаче на рассмотрение коллегиального органа управления общества (пункт 4 статьи 653) или коллегиального исполнительного органа общества вопросов, отнесенных законом к компетенции общего собрания участников хозяйственного общества, за исключением вопросов:\n\nвнесения изменений в устав хозяйственного общества, утверждения устава в новой редакции;\n\nреорганизации или ликвидации хозяйственного общества;\n\nопределения количественного состава коллегиального органа управления общества (пункт 4 статьи 653) и коллегиального исполнительного органа (если его формирование отнесено к компетенции общего собрания участников хозяйственного общества), избрания их членов и досрочного прекращения их полномочий;\n\nопределения количества, номинальной стоимости, категории (типа) объявленных акций и прав, предоставляемых этими акциями;\n\nувеличения уставного капитала общества с ограниченной ответственностью непропорционально долям его участников или за счет принятия третьего лица в состав участников такого общества;\n\nутверждения не являющихся учредительными документами внутреннего регламента или иных внутренних документов (пункт 5 статьи 52) хозяйственного общества;\n\n2) о закреплении функций коллегиального исполнительного органа общества за коллегиальным органом управления общества (пункт 4 статьи 653) полностью или в части либо об отказе от создания коллегиального исполнительного органа, если его функции осуществляются указанным коллегиальным органом управления;\n\n3) о передаче единоличному исполнительному органу общества функций коллегиального исполнительного органа общества;\n\n4) об отсутствии в обществе ревизионной комиссии или о ее создании исключительно в случаях, предусмотренных уставом общества;\n\n5) о порядке, отличном от установленного законами и иными правовыми актами порядка принятия решений о проведении заседания общего собрания или заочного голосования участников общества, порядка подготовки и проведения заседания общего собрания или заочного голосования участников общества, а также порядка принятия решений общего собрания, при условии, что такие изменения не лишают участников общества права на участие в заседании общего собрания общества или в заочном голосовании и на получение информации о них; (В редакции Федерального закона от 28.06.2021 № 225-ФЗ)\n\n6) о требованиях, отличных от установленных законами и иными правовыми актами требований к количественному составу, порядку формирования и проведения заседаний коллегиального органа управления общества (пункт 4 статьи 653) или коллегиального исполнительного органа общества;\n\n7) о порядке осуществления преимущественного права покупки доли или части доли в уставном капитале общества с ограниченной ответственностью или преимущественного права приобретения размещаемых акционерным обществом акций либо ценных бумаг, конвертируемых в его акции, а также о максимальной доле участия одного участника общества с ограниченной ответственностью в уставном капитале общества;\n\n8) об отнесении к компетенции общего собрания акционеров вопросов, не относящихся к ней в соответствии с настоящим Кодексом или законом об акционерных обществах;\n\n9) иные положения в случаях, предусмотренных законами о хозяйственных обществах.\n\n4. В случаях, если положения, предусмотренные пунктом 3 настоящей статьи, не относятся к числу положений, подлежащих в соответствии с настоящим Кодексом или другими законами обязательному включению в устав непубличного хозяйственного общества, они могут быть предусмотрены корпоративным договором, сторонами которого являются все участники этого общества.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.3. Публичные и непубличные общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"820b0e52dccb3e6fdf67ea7606b7b28088f91727edc0b62782ba471fe361264e"},{"code_id":"GK_RF","article_number":"67","version_date":"1994-11-30","article_text":"1. Участник хозяйственного товарищества или общества наряду с правами, предусмотренными для участников корпораций пунктом 1 статьи 652 настоящего Кодекса, также вправе:\n\nпринимать участие в распределении прибыли товарищества или общества, участником которого он является;\n\nполучать в случае ликвидации товарищества или общества часть имущества, оставшегося после расчетов с кредиторами, или его стоимость;\n\nтребовать исключения другого участника из товарищества или общества (кроме публичных акционерных обществ) в судебном порядке с выплатой ему действительной стоимости его доли участия, если такой участник своими действиями (бездействием) причинил существенный вред товариществу или обществу либо иным образом существенно затрудняет его деятельность и достижение целей, ради которых оно создавалось, в том числе грубо нарушая свои обязанности, предусмотренные законом или учредительными документами товарищества или общества. Отказ от этого права или его ограничение ничтожны.\n\nУчастники хозяйственных товариществ или обществ могут иметь и другие права, предусмотренные настоящим Кодексом, законами о хозяйственных обществах, учредительными документами товарищества или общества.\n\n2. Участник хозяйственного товарищества или общества наряду с обязанностями, предусмотренными для участников корпораций пунктом 4 статьи 652 настоящего Кодекса, также обязан вносить вклады в уставный (складочный) капитал товарищества или общества, участником которого он является, в порядке, в размерах, способами, которые предусмотрены учредительным документом хозяйственного товарищества или общества, и вклады в иное имущество хозяйственного товарищества или общества.\n\nУчастники хозяйственных товариществ и обществ могут нести и другие обязанности, предусмотренные законом и их учредительными документами.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67. Права и обязанности участника хозяйственного товарищества и общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85d3546c5e06ab10d43de04585c1ddbdbf80f2a2c6a7f78a04bc311ce51d2d6f"},{"code_id":"GK_RF","article_number":"67.1","version_date":"1994-11-30","article_text":"1. Управление в полном товариществе и товариществе на вере осуществляется в порядке, установленном статьями 71 и 84 настоящего Кодекса.\n\n2. К исключительной компетенции общего собрания участников хозяйственного общества наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относятся:\n\n1) изменение размера уставного капитала общества, если иное не предусмотрено законами о хозяйственных обществах;\n\n2) принятие решения о передаче полномочий единоличного исполнительного органа общества другому хозяйст\n\nвенному обществу (управляющей организации) или индивидуальному предпринимателю (управляющему), а также утверждение такой управляющей организации или такого управляющего и условий договора с такой управляющей организацией или с таким управляющим, если уставом общества решение указанных вопросов не отнесено к компетенции коллегиального органа управления общества (пункт 4 статьи 653);\n\n3) распределение прибылей и убытков общества.\n\n1) публичного акционерного общества лицом, осуществляющим ведение реестра акционеров такого общества и выполняющим функции счетной комиссии (пункт 4 статьи 97);\n\n2) непубличного акционерного общества путем нотариального удостоверения или удостоверения лицом, осуществляющим ведение реестра акционеров такого общества и выполняющим функции счетной комиссии;\n\n3) общества с ограниченной ответственностью путем нотариального удостоверения, если иной способ (подписание протокола всеми участниками или частью участников; с использованием технических средств, позволяющих достоверно установить факт принятия решения; иным способом, не противоречащим закону) не предусмотрен уставом такого общества либо решением общего собрания участников общества, принятым участниками общества единогласно.\n\nАудит бухгалтерской (финансовой) отчетности общества с ограниченной ответственностью проводится по требованию любого из участников общества.\n\n(Пункт в редакции  Федерального закона от 16.04.2022 № 99-ФЗ)\n\nАудит бухгалтерской (финансовой) отчетности акционерного общества проводится по требованию акционеров, совокупная доля участия которых в уставном капитале общества составляет десять и более процентов, в отношении публичного акционерного общества аудиторской организацией, а в отношении непубличного акционерного общества аудиторской организацией или индивидуальным аудитором, которые должны быть независимы в соответствии с законом об аудиторской деятельности.\n\n(Пункт в редакции  Федерального закона от 16.04.2022 № 99-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.1. Особенности управления и контроля в хозяйственных товариществах и обществах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"227a6aa59c6e144fb0b218c51e8f48094ce4bf986436d3403eb7f079a36a8e45"},{"code_id":"GK_RF","article_number":"67.2","version_date":"1994-11-30","article_text":"Условия корпоративного договора, противоречащие правилам абзаца первого настоящего пункта, ничтожны.\n\nКорпоративным договором может быть установлена обязанность его сторон проголосовать на общем собрании участников общества за включение в устав общества положений, определяющих структуру органов общества и их компетенцию, если в соответствии с настоящим Кодексом и законами о хозяйственных обществах допускается изменение структуры органов общества и их компетенции уставом общества.\n\nИнформация о корпоративном договоре, заключенном акционерами публичного акционерного общества, должна быть раскрыта в пределах, в порядке и на условиях, которые предусмотрены законом об акционерных обществах.\n\nЕсли иное не установлено законом, информация о содержании корпоративного договора, заключенного участниками непубличного общества, не подлежит раскрытию и является конфиденциальной.\n\nПризнание решения органа хозяйственного общества недействительным в соответствии с настоящим пунктом само по себе не влечет недействительности сделок хозяйственного общества с третьими лицами, совершенных на основании такого решения.\n\nСделка, заключенная стороной корпоративного договора в нарушение этого договора, может быть признана судом недействительной по иску участника корпоративного договора только в случае, если другая сторона сделки знала или должна была знать об ограничениях, предусмотренных корпоративным договором.\n\n10. Правила о корпоративном договоре соответственно применяются к соглашению о создании хозяйственного общества, если иное не установлено законом или не вытекает из существа отношений сторон такого соглашения.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.2. Корпоративный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f060b1887954aa6c2bb725ef055aac87ef2c804596d83148a7a7f2043956e245"}]$law7d0028$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
